// packages/core/src/pricing.ts
var CURRENCIES = ["KES", "USD"];
function currencyAllowed(provider, currency, pesapalCurrencies2 = ["KES"]) {
  if (provider === "paypal") return currency === "USD";
  return pesapalCurrencies2.includes(currency);
}
function planMinor(plan, currency) {
  const minor = currency === "KES" ? plan.price_kes * 100 : plan.price_usd_cents;
  if (!Number.isSafeInteger(minor) || minor < 0) throw Error("Invalid price");
  return minor;
}
function minorToMajorString(minor) {
  if (!Number.isSafeInteger(minor) || minor < 0) throw Error("Invalid amount");
  return `${Math.floor(minor / 100)}.${String(minor % 100).padStart(2, "0")}`;
}
function amountsMatch(expectedMinor, reportedMajor) {
  const n = typeof reportedMajor === "string" ? Number(reportedMajor) : reportedMajor;
  if (typeof n !== "number" || !Number.isFinite(n) || n <= 0) return false;
  return Math.round(n * 100) === expectedMinor && Math.abs(n * 100 - expectedMinor) < 1e-3;
}
function paypalOrderVerified(order, expected) {
  if (!order || order.status !== "COMPLETED") return false;
  const unit = order.purchase_units?.[0];
  const capture = unit?.payments?.captures?.[0];
  if (!unit || !capture || capture.status !== "COMPLETED") return false;
  const ref = unit.custom_id ?? capture.custom_id;
  return ref === expected.reference && capture.amount?.currency_code === expected.currency && amountsMatch(expected.minor, capture.amount?.value);
}
function pesapalVerified(status, expected) {
  if (!status) return false;
  const completed = status.status_code === 1 || String(status.payment_status_description || "").toLowerCase() === "completed";
  return completed && String(status.currency || "").toUpperCase() === expected.currency && amountsMatch(expected.minor, status.amount) && String(status.merchant_reference || "") === expected.reference;
}

// apps/api/src/services/payments.ts
async function jsonFetch(url2, init) {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 2e4);
  try {
    const r = await fetch(url2, { ...init, signal: ctl.signal });
    const txt = await r.text();
    let data;
    try {
      data = JSON.parse(txt);
    } catch {
      throw new ApiError(502, "Invalid response from payment provider");
    }
    if (!r.ok) throw new ApiError(502, "Payment provider unavailable");
    return data;
  } finally {
    clearTimeout(timer);
  }
}
function pesapalCurrencies() {
  const list = (process.env.PESAPAL_CURRENCIES || "KES").split(",").map((x) => x.trim().toUpperCase()).filter((x) => CURRENCIES.includes(x));
  return list.length ? list : ["KES"];
}
function paymentOptions() {
  const pesapal = Boolean(process.env.PESAPAL_CONSUMER_KEY && process.env.PESAPAL_CONSUMER_SECRET && process.env.PESAPAL_IPN_ID);
  const paypal = Boolean(process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET);
  return { pesapal: { enabled: pesapal, currencies: pesapalCurrencies() }, paypal: { enabled: paypal, currencies: ["USD"] } };
}
function pesapalBase() {
  return process.env.PESAPAL_ENV === "live" ? "https://pay.pesapal.com/v3" : "https://cybqa.pesapal.com/pesapalv3";
}
async function pesapalToken() {
  const key = process.env.PESAPAL_CONSUMER_KEY, secret = process.env.PESAPAL_CONSUMER_SECRET;
  assert(key && secret, 503, "Pesapal credentials are not configured");
  const r = await jsonFetch(`${pesapalBase()}/api/Auth/RequestToken`, { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify({ consumer_key: key, consumer_secret: secret }) });
  assert(r.token, 502, "Pesapal authentication failed");
  return String(r.token);
}
async function startPesapal(p) {
  assert(process.env.PESAPAL_IPN_ID, 503, "Pesapal IPN has not been configured");
  const token2 = await pesapalToken();
  const r = await jsonFetch(`${pesapalBase()}/api/Transactions/SubmitOrderRequest`, { method: "POST", headers: { Authorization: `Bearer ${token2}`, "Content-Type": "application/json", Accept: "application/json" }, body: JSON.stringify({ id: p.reference, currency: p.currency, amount: Number(minorToMajorString(p.minor)), description: p.description, callback_url: `${env.PUBLIC_BASE_URL}/billing-return`, notification_id: process.env.PESAPAL_IPN_ID, billing_address: { email_address: p.email } }) });
  assert(r.order_tracking_id && r.redirect_url, 502, "Pesapal did not return a valid checkout");
  return r;
}
async function verifyPesapal(trackingId) {
  const token2 = await pesapalToken(), u = new URL(`${pesapalBase()}/api/Transactions/GetTransactionStatus`);
  u.searchParams.set("orderTrackingId", trackingId);
  return jsonFetch(u.toString(), { headers: { Authorization: `Bearer ${token2}`, Accept: "application/json" } });
}
function paypalBase() {
  return process.env.PAYPAL_ENV === "live" ? "https://api-m.paypal.com" : "https://api-m.sandbox.paypal.com";
}
var paypalCache = null;
async function paypalToken() {
  if (paypalCache && paypalCache.expires > Date.now() + 3e4) return paypalCache.token;
  const id = process.env.PAYPAL_CLIENT_ID, secret = process.env.PAYPAL_CLIENT_SECRET;
  assert(id && secret, 503, "PayPal credentials are not configured");
  const r = await jsonFetch(`${paypalBase()}/v1/oauth2/token`, { method: "POST", headers: { Authorization: `Basic ${Buffer.from(`${id}:${secret}`).toString("base64")}`, "Content-Type": "application/x-www-form-urlencoded" }, body: "grant_type=client_credentials" });
  assert(r.access_token, 502, "PayPal authentication failed");
  paypalCache = { token: String(r.access_token), expires: Date.now() + Number(r.expires_in || 300) * 1e3 };
  return paypalCache.token;
}
async function paypalFetch(path, init = {}) {
  const token2 = await paypalToken();
  return jsonFetch(`${paypalBase()}${path}`, { ...init, headers: { Authorization: `Bearer ${token2}`, "Content-Type": "application/json", Accept: "application/json", ...init.headers || {} } });
}
async function startPaypal(p) {
  const base = env.PUBLIC_BASE_URL;
  const r = await paypalFetch("/v2/checkout/orders", { method: "POST", headers: { "PayPal-Request-Id": p.reference }, body: JSON.stringify({
    intent: "CAPTURE",
    purchase_units: [{ reference_id: p.reference, custom_id: p.reference, description: p.description.slice(0, 120), amount: { currency_code: "USD", value: minorToMajorString(p.minor) } }],
    payment_source: { paypal: { experience_context: {
      brand_name: "SocialOrbit",
      user_action: "PAY_NOW",
      shipping_preference: "NO_SHIPPING",
      return_url: `${base}/billing-return?provider=paypal&w=${encodeURIComponent(p.workspaceId)}`,
      cancel_url: `${base}/billing-return?provider=paypal&cancelled=1`
    } } }
  }) });
  const link = (r.links || []).find((l) => l.rel === "payer-action" || l.rel === "approve");
  assert(r.id && link?.href && String(link.href).startsWith("https://"), 502, "PayPal did not return a valid checkout");
  return { orderId: String(r.id), approveUrl: String(link.href) };
}
async function getPaypalOrder(orderId) {
  return paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}`);
}
async function capturePaypalOrder(orderId) {
  try {
    return await paypalFetch(`/v2/checkout/orders/${encodeURIComponent(orderId)}/capture`, { method: "POST", headers: { "PayPal-Request-Id": `capture-${orderId}` }, body: "{}" });
  } catch {
    return getPaypalOrder(orderId);
  }
}
async function verifyPaypalWebhook(headers, event) {
  const webhookId = process.env.PAYPAL_WEBHOOK_ID;
  if (!webhookId) return false;
  const h = (k) => String(headers[k] || "");
  const r = await paypalFetch("/v1/notifications/verify-webhook-signature", { method: "POST", body: JSON.stringify({
    auth_algo: h("paypal-auth-algo"),
    cert_url: h("paypal-cert-url"),
    transmission_id: h("paypal-transmission-id"),
    transmission_sig: h("paypal-transmission-sig"),
    transmission_time: h("paypal-transmission-time"),
    webhook_id: webhookId,
    webhook_event: event
  }) });
  return r.verification_status === "SUCCESS";
}

// apps/api/src/middleware/auth.ts
import { z } from "zod";
var uuid = z.string().uuid();
function assuranceLevel(token2) {
  try {
    return String(JSON.parse(Buffer.from(token2.split(".")[1] || "", "base64url").toString()).aal || "");
  } catch {
    return "";
  }
}
var requireAuth = asyncRoute(async (req, _res, next) => {
  const header = req.headers.authorization || "";
  assert(header.startsWith("Bearer "), 401, "Sign in required", "UNAUTHENTICATED");
  const token2 = header.slice(7).trim();
  assert(token2.length > 30, 401, "Invalid session");
  const { data, error } = await database().auth.getUser(token2);
  assert(!error && data.user, 401, "Session expired or invalid", "INVALID_SESSION");
  const profile = await database().from("profiles").select("status").eq("id", data.user.id).maybeSingle();
  assert(!profile.error, 503, "Account status unavailable");
  assert(profile.data?.status !== "suspended", 403, "Account suspended; contact support", "ACCOUNT_SUSPENDED");
  req.actor = { id: data.user.id, email: data.user.email || "" };
  req.aal = assuranceLevel(token2);
  next();
});
var hierarchy = { owner: 5, admin: 4, editor: 3, analyst: 2, viewer: 1 };
function needSpace(minimum = "viewer") {
  return asyncRoute(async (req, _res, next) => {
    assert(req.actor, 401, "Sign in required");
    const id = uuid.parse(req.params.workspaceId || req.headers["x-workspace-id"]);
    const { data, error } = await database().from("workspace_members").select("role").eq("workspace_id", id).eq("user_id", req.actor.id).maybeSingle();
    assert(!error, 503, "Membership lookup unavailable");
    assert(data, 403, "Workspace access denied", "WORKSPACE_FORBIDDEN");
    const role = data.role;
    assert(hierarchy[role] >= hierarchy[minimum], 403, "Insufficient workspace privileges", "ROLE_FORBIDDEN");
    req.space = { id, role };
    next();
  });
}
function needAdmin(allowedRoles = ["super_admin"]) {
  return asyncRoute(async (req, _res, next) => {
    assert(req.actor, 401, "Sign in required");
    const { data, error } = await database().from("admin_roles").select("role").eq("user_id", req.actor.id).maybeSingle();
    assert(!error, 503, "Admin role lookup unavailable");
    assert(data && allowedRoles.includes(data.role), 403, "Admin access denied", "ADMIN_FORBIDDEN");
    assert(!env.ADMIN_REQUIRE_MFA || req.aal === "aal2", 403, "Two-factor authentication is required for administrators", "ADMIN_MFA_REQUIRED");
    req.adminRole = data.role;
    next();
  });
}
function actor(req) {
  assert(req.actor, 401, "Sign in required");
  return req.actor;
}
function workspace(req) {
  assert(req.space, 403, "Workspace access denied");
  return req.space;
}

