// apps/api/src/routes/ai.ts
import { Router as Router11 } from "express";
import { z as z8 } from "zod";

// apps/api/src/services/ai.ts
var SYSTEM = {
  caption: "You write platform-specific, factual and engaging social captions. Do not invent claims. Return a ready-to-review caption.",
  rewrite: "Improve clarity and engagement without changing facts. Return the revised post only.",
  hashtags: "Suggest relevant, not spammy hashtags. Avoid unsupported claims.",
  translate: "Translate accurately while preserving meaning and tone. Clearly distinguish hashtags when adaptation is needed.",
  support: "Answer using only verified support documentation supplied in the prompt; if unavailable, say you do not know and recommend a support ticket."
};
async function postJSON(url2, body2, headers) {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), 3e4);
  try {
    const r = await fetch(url2, { method: "POST", headers: { "Content-Type": "application/json", ...headers }, body: JSON.stringify(body2), signal: ctl.signal });
    const t = await r.text();
    let obj;
    try {
      obj = JSON.parse(t);
    } catch {
      throw new ApiError(502, "AI provider returned invalid JSON");
    }
    ;
    if (!r.ok) throw new ApiError(502, "AI provider error; try again");
    return obj;
  } finally {
    clearTimeout(timer);
  }
}
async function generateAI(input) {
  const instruction = `${SYSTEM[input.task]} ${input.platform ? "Target social platform: " + input.platform + "." : ""} ${input.language ? "Output language: " + input.language + "." : ""}`;
  const providers = [
    { name: "openrouter", key: process.env.OPENROUTER_API_KEY, model: process.env.OPENROUTER_TEXT_MODEL, base: "https://openrouter.ai/api/v1/chat/completions" },
    { name: "groq", key: process.env.GROQ_API_KEY, model: process.env.GROQ_TEXT_MODEL, base: "https://api.groq.com/openai/v1/chat/completions" },
    { name: "gemini", key: process.env.GEMINI_API_KEY, model: process.env.GEMINI_TEXT_MODEL, base: "https://generativelanguage.googleapis.com/v1beta/models" }
  ];
  const enabled = providers.filter((x) => x.key && x.model);
  assert(enabled.length, 503, "No AI provider is configured");
  const errors = [];
  for (const p of enabled) {
    try {
      if (p.name === "gemini") {
        const data2 = await postJSON(`${p.base}/${encodeURIComponent(p.model)}:generateContent?key=${encodeURIComponent(p.key)}`, {
          systemInstruction: { parts: [{ text: instruction }] },
          contents: [{ role: "user", parts: [{ text: input.prompt }] }],
          generationConfig: { temperature: 0.65, maxOutputTokens: 900 }
        }, {});
        const text2 = (data2.candidates?.[0]?.content?.parts || []).map((x) => x.text || "").join("").trim();
        assert(text2.length, 502, "AI returned empty content");
        return { text: text2, provider: p.name, model: p.model, tokensIn: data2.usageMetadata?.promptTokenCount || 0, tokensOut: data2.usageMetadata?.candidatesTokenCount || 0 };
      }
      const data = await postJSON(p.base, { model: p.model, messages: [{ role: "system", content: instruction }, { role: "user", content: input.prompt }], temperature: 0.65, max_tokens: 900 }, { Authorization: `Bearer ${p.key}` });
      const text = String(data.choices?.[0]?.message?.content || "").trim();
      assert(text.length, 502, "AI returned empty content");
      return { text, provider: p.name, model: p.model, tokensIn: data.usage?.prompt_tokens || 0, tokensOut: data.usage?.completion_tokens || 0 };
    } catch (e) {
      errors.push(p.name);
      console.error("AI provider unavailable:", p.name, e instanceof Error ? e.message : "unknown");
    }
  }
  throw new ApiError(502, "All configured AI providers are unavailable");
}

// apps/api/src/routes/ai.ts
var aiRoutes = Router11({ mergeParams: true });
aiRoutes.use(requireAuth, needSpace());
var task = z8.object({ task: z8.enum(["caption", "rewrite", "hashtags", "translate"]), prompt: z8.string().trim().min(10).max(5e3), platform: z8.enum(["facebook", "instagram", "youtube", "tiktok", "x", "linkedin"]).optional(), language: z8.enum(["en", "sw"]).optional() }).strict();
aiRoutes.post("/text", needSpace("editor"), asyncRoute(async (req, res) => {
  const input = task.parse(req.body), db = database(), wid = workspace(req).id, user = actor(req);
  const idempotency = `ai:text:${user.id}:${crypto.randomUUID()}`;
  const reserved = await db.rpc("credit_reserve", { p_workspace: wid, p_kind: "text", p_units: 1, p_key: idempotency, p_reason: input.task });
  assert(!reserved.error && reserved.data, 402, "Text AI credits exhausted or unavailable", "CREDITS_REQUIRED");
  const tx = reserved.data;
  const reqRow = await db.from("ai_requests").insert({ workspace_id: wid, user_id: user.id, kind: input.task, status: "processing", credit_tx_id: tx }).select("id").single();
  if (reqRow.error) {
    await db.rpc("credit_release", { p_id: tx });
    throw Error("Could not record AI request");
  }
  try {
    const result = await generateAI(input);
    const charge = await db.rpc("credit_settle", { p_id: tx });
    assert(!charge.error, 503, "Unable to settle AI credit");
    await db.from("ai_requests").update({ status: "completed", provider: result.provider, model: result.model, tokens_in: result.tokensIn, tokens_out: result.tokensOut }).eq("id", reqRow.data.id);
    res.json({ id: reqRow.data.id, text: result.text, model: result.model, provider: result.provider, creditsCharged: 1 });
  } catch (e) {
    await db.rpc("credit_release", { p_id: tx });
    await db.from("ai_requests").update({ status: "failed", error_message: e instanceof Error ? e.message : "provider unavailable" }).eq("id", reqRow.data.id);
    throw e;
  }
}));

