  const id = uuid.parse(req.params.id), wid = workspace(req).id, db = database();
  const r = await db.from("publishing_jobs").update({ status: "cancelled", updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id).eq("workspace_id", wid).in("status", ["scheduled", "queued"]).select("id,credit_tx_id").maybeSingle();
